func (b *backend) RunCommand(ctx context.Context, id string, request *sandbox.ExecOptions) (*sandbox.ExecResult, error) {
	instance, err := b.processSandbox(ctx, id, "run")
	if err != nil {
		return nil, err
	}
	command, err := blaxelCommand(request)
	if err != nil {
		return nil, err
	}
	timeout, err := commandTimeout("run", request.GetTimeout())
	if err != nil {
		return nil, err
	}
	started, err := instance.Process.New(ctx, processRequest(command, timeout, request))
	if err != nil {
		return nil, mapProviderError(err, "run")
	}
	return finishProcess(ctx, instance, started, timeout)
}

// processRequest builds the Blaxel Process.New body. Timeout 0 disables
// Blaxel's default auto-kill. WaitForCompletion is only set for 1–60s.
func processRequest(command string, timeout time.Duration, request *sandbox.ExecOptions) blaxel.ProcessRequestParam {
